import { computed, ref } from 'vue';

import { UserPreferences } from '@game-studio/settings';

import { gameConfig } from './config-model';
import { device } from '../services/device';
import { eventEmitter } from '../services/event-emitter';
import { IChatSettingsOption } from '../views/settings-menu/chat-colours';
import { queryStringParams } from '../services/query-string';
import { PrizeLeagueManager } from '../services/prize-league/prize-league-manager';
import { inversifyContainer } from '../inversify/container';
import { Injects } from '..';

export type CompanionMode = 'side' | 'bottom';
export type CompanionPanel = 'chat' | 'gameInGame' | 'prizeLeague' | null;
export type SubGameState = 'list' | 'game';

// declaring the variables outside of the function to maintain state across multiple calls to useCompanionState
const mode = ref<CompanionMode>('side');
const activePanel = ref<CompanionPanel>(null);
const menuHeight = ref(0);
const gigPanelHeight = ref(0);
const prizeLeaguePanelHeight = ref(0);
const sideModeWidth = ref(301);
const isLobbyEnabled = ref(false);

const isGameInGameEnabled = ref(false);
const gameInGameState = ref<SubGameState>('list');
const isGamePopoutMessageVisible = ref(false);

const isPrizeLeagueEnabled = ref(false);
const isPrizeLeagueNotificationVisible = ref(false);

const isChatFullScreen = ref(false);
const isChatEnabled = ref(false);
const isChatNotificationVisible = ref(false);
const chatColours = ref<IChatSettingsOption[]>([]);
const canHideChat = ref(false);
const isEnabled = ref(true);

const chatPanelHeight = computed(() => {
    return (mode.value === 'side' ? device.viewport.height : device.viewport.height - device.gameHeightScaledToWidth) - menuHeight.value;
});

const isActionMenuEnabled = computed(() => {
    const isChatButtonEnabled = !device.type.isDesktop && isChatEnabled.value && canHideChat.value;
    if (!isGameInGameEnabled.value && !isLobbyEnabled.value && !isPrizeLeagueEnabled.value && (!isChatButtonEnabled)) {
        // disables the action menu if all features within it are disabled to avoid empty menu showing
        // if settings is the only button still disable since thats also accessible via the cabinet
        return false;
    }
    return gameConfig.features.enableActionMenu;
});

const width = computed(() => { return mode.value === 'side' ? sideModeWidth.value : device.viewport.width; });
const isPanelOpen = computed(() => activePanel.value !== null);
const isGameInGameOpen = computed(() => activePanel.value === 'gameInGame');
const isSubGameOpen = computed(() => gameInGameState.value === 'game');
const isChatOpen = computed(() => activePanel.value === 'chat');
const isPrizeLeagueOpen = computed(() => activePanel.value === 'prizeLeague');
const isGigNotificationVisible = computed(() => !isGameInGameOpen.value && isSubGameOpen.value);

export function useCompanionState() {
    function initialise() {
        isChatEnabled.value = gameConfig.features.enableChat;
        isGameInGameEnabled.value = gameConfig.features.enableGameInGame;
        isLobbyEnabled.value = gameConfig.features.enableLobby;
        canHideChat.value = gameConfig.features.canHideChat;
        isEnabled.value = gameConfig.features.enableCompanionPanel;
        isPrizeLeagueEnabled.value = gameConfig.features.enablePrizeLeague && queryStringParams.launchedFrom === 'arcade'; //Remove arcade check to enable on core site

        if (isGameInGameEnabled.value) {
            // Show game-in-game by default or if the player previously had it open
            const showGameInGame = UserPreferences.getPreference('isGameInGameVisible', true, false, true);
            if (showGameInGame) {
                show('gameInGame');
            }
        }

        if (isPrizeLeagueEnabled.value) {
            const prizeLeagueManager = inversifyContainer.get<PrizeLeagueManager>(Injects.PrizeLeagueManager);
            const firstTournament = prizeLeagueManager.tournamentList.value[0];
            if ((firstTournament && firstTournament.secondsToStart < 1800) || !isChatEnabled.value) { // Show prize league panel if tournament is starting within 30 mins or chat is disabled (to give players access to tournament info and opt-in)
                show('prizeLeague');
            }
        }

        if (canHideChat.value === false && activePanel.value === null) {
            show('chat');
        }

        updateDisplayMode();

        if (isChatEnabled.value) {
            device.orientation.on('onOrientationStateChanged', () => updateDisplayMode());
        }
    }

    function setChatColours(colours: IChatSettingsOption[]): void {
        chatColours.value = colours;
    }

    function updateDisplayMode(): void {
        mode.value = device.type.isDesktop ? 'side' : 'bottom';
    }

    function hide(): void {
        if (canHideChat.value === false) {
            if (activePanel.value === 'chat') { return; }
            setPanel('chat');
            return;
        }

        setPanel(null);
    }

    function show(panel: Exclude<CompanionPanel, null>): void {
        setPanel(panel);
    }

    function setPanel(panel: CompanionPanel): void {
        if (activePanel.value === panel || isEnabled.value === false) { return; }

        activePanel.value = panel;
        updateDisplayMode();
        eventEmitter.emit('COMPANION_PANEL_CHANGED', activePanel.value);
        UserPreferences.setPreference('isGameInGameVisible', panel === 'gameInGame', false, true);
    }

    return {
        mode,
        activePanel,
        gameInGameState,
        isPanelOpen,
        isActionMenuEnabled,
        isPrizeLeagueEnabled,
        isPrizeLeagueNotificationVisible,
        isChatEnabled,
        isGameInGameEnabled,
        isLobbyEnabled,
        isChatNotificationVisible,
        isGigNotificationVisible,
        isGamePopoutMessageVisible,
        menuHeight,
        chatPanelHeight,
        gigPanelHeight,
        prizeLeaguePanelHeight,
        width,
        chatColours,
        isChatFullScreen,
        isGameInGameOpen,
        isSubGameOpen,
        isChatOpen,
        isEnabled,
        isPrizeLeagueOpen,
        initialise,
        setChatColours,
        hide,
        show
    };
}
